import java.util.*;

public class Solution {
    static class LFU {
        private final int capacidade;
        private final Map<Integer, int[]> dados = new HashMap<>();              // chave -> {valor, freq}
        private final Map<Integer, LinkedHashSet<Integer>> porFreq = new HashMap<>(); // ordem de inserção = LRU
        private int minFreq;

        LFU(int capacidade) { this.capacidade = capacidade; }

        private void tocar(int key, int[] d) {
            LinkedHashSet<Integer> grupo = porFreq.get(d[1]);
            grupo.remove(key);
            if (grupo.isEmpty()) {
                porFreq.remove(d[1]);
                if (minFreq == d[1]) minFreq++;
            }
            d[1]++;
            porFreq.computeIfAbsent(d[1], f -> new LinkedHashSet<>()).add(key);
        }

        int get(int key) {
            int[] d = dados.get(key);
            if (d == null) return -1;
            tocar(key, d);
            return d[0];
        }

        void put(int key, int value) {
            if (capacidade == 0) return;
            int[] d = dados.get(key);
            if (d != null) {
                d[0] = value;
                tocar(key, d);
                return;
            }
            if (dados.size() == capacidade) {
                LinkedHashSet<Integer> grupo = porFreq.get(minFreq);
                int vitima = grupo.iterator().next(); // menos recente entre os menos frequentes
                grupo.remove(vitima);
                if (grupo.isEmpty()) porFreq.remove(minFreq);
                dados.remove(vitima);
            }
            dados.put(key, new int[]{value, 1});
            porFreq.computeIfAbsent(1, f -> new LinkedHashSet<>()).add(key);
            minFreq = 1;
        }
    }
}

