import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void sequenciaClassica() {
        var c = new Solution.LFU(2);
        c.put(1, 1); c.put(2, 2);
        assertEquals(1, c.get(1));   // freq(1)=2
        c.put(3, 3);                 // evicta 2
        assertEquals(-1, c.get(2));
        assertEquals(3, c.get(3));   // freq(3)=2
        c.put(4, 4);                 // empate 1 e 3 (freq 2): evicta 1, o menos recente
        assertEquals(-1, c.get(1));
        assertEquals(3, c.get(3));
        assertEquals(4, c.get(4));
    }

    @Test void atualizarContaUso() {
        var c = new Solution.LFU(2);
        c.put(1, 1); c.put(2, 2);
        c.put(1, 10);                // freq(1)=2
        c.put(3, 3);                 // evicta 2
        assertEquals(10, c.get(1));
        assertEquals(-1, c.get(2));
    }

    @Test void capacidadeZero() {
        var c = new Solution.LFU(0);
        c.put(1, 1);
        assertEquals(-1, c.get(1));
    }

    @Test void volume() {
        var c = new Solution.LFU(1000);
        for (int i = 0; i < 300_000; i++) {
            c.put(i % 5000, i);
            c.get(i % 37);
        }
        assertTrue(c.get(36) >= 0);
    }
}

statement:
Implemente um Bloom filter sobre `long[]` com `k` funções de hash derivadas de dois hashes
(`h1 + i·h2`, técnica de Kirsch–Mitzenmacher).

## Contrato

```java
static class Bloom {
    Bloom(int bits, int k);
    void add(String s);
    boolean talvezContem(String s);
}
```

## Restrições

- **Nunca** dá falso negativo.
- Com 1 milhão de bits, k = 7 e 100 mil elementos, a taxa de falso positivo medida fica abaixo de 2%.

