solutionCode:
public class Solution {
    static class Bloom {
        private final long[] bits;
        private final int m, k;

        Bloom(int bits, int k) {
            this.bits = new long[(bits + 63) / 64];
            this.m = bits;
            this.k = k;
        }

        private static int mix(int h) { // espalha os bits (finalizador do MurmurHash3)
            h ^= h >>> 16; h *= 0x85ebca6b; h ^= h >>> 13; h *= 0xc2b2ae35; h ^= h >>> 16;
            return h;
        }

        private int pos(String s, int i) {
            int h1 = mix(s.hashCode()), h2 = mix(h1 ^ 0x9e3779b9) | 1;
            return Math.floorMod(h1 + i * h2, m);
        }

        void add(String s) {
            for (int i = 0; i < k; i++) {
                int p = pos(s, i);
                bits[p >>> 6] |= 1L << (p & 63);
            }
        }

        // Algum bit zerado prova ausência; todos ligados = "talvez".
        boolean talvezContem(String s) {
            for (int i = 0; i < k; i++) {
                int p = pos(s, i);
                if ((bits[p >>> 6] & (1L << (p & 63))) == 0) return false;
            }
            return true;
        }
    }
}

