import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void semFalsoNegativo() {
        var b = new Solution.Bloom(1_000_000, 7);
        for (int i = 0; i < 100_000; i++) b.add("user:" + i);
        for (int i = 0; i < 100_000; i++) assertTrue(b.talvezContem("user:" + i), "user:" + i);
    }

    @Test void taxaDeFalsoPositivo() {
        var b = new Solution.Bloom(1_000_000, 7);
        for (int i = 0; i < 100_000; i++) b.add("user:" + i);
        int fp = 0;
        for (int i = 0; i < 100_000; i++) if (b.talvezContem("outro:" + i)) fp++;
        assertTrue(fp < 2000, fp + " falsos positivos em 100 000");
    }

    @Test void vazioNaoContemNada() {
        var b = new Solution.Bloom(1024, 3);
        assertFalse(b.talvezContem("x"));
    }
}
